import {
  KARDO_MARK_VIEW_HEIGHT,
  KARDO_MARK_VIEW_WIDTH,
  kardoMarkDot,
  kardoMarkInnerWave,
  kardoMarkOuterWave,
  kardoMarkRing,
} from "./kardo-mark-data.js";
import type { PathCommand } from "./types.js";

/**
 * The Kardo mark printed on QR exports: the official symbol (ring, centre
 * dot and two signal waves) from the 2026-10-01 masters in Docs/Marca, as
 * filled outlines (`kardo-mark-data.ts`, generated by
 * scripts/brand/build-brand.mjs). It is drawn in one ink chosen for
 * contrast; the inner wave goes lighter, like the light aqua of the logo.
 */

export const KARDO_MARK_ASPECT = KARDO_MARK_VIEW_WIDTH / KARDO_MARK_VIEW_HEIGHT;

type MarkPath = {
  d: readonly PathCommand[];
  fillRule: "nonzero" | "evenodd";
  opacity?: number;
};

const rawPaths: readonly MarkPath[] = [
  { d: kardoMarkRing, fillRule: "nonzero" },
  { d: kardoMarkDot, fillRule: "nonzero" },
  { d: kardoMarkOuterWave, fillRule: "nonzero" },
  { d: kardoMarkInnerWave, fillRule: "nonzero", opacity: 0.6 },
];

function scaleCommand(
  command: PathCommand,
  x: number,
  y: number,
  scale: number,
): PathCommand {
  if (command[0] === "Z") return command;
  if (command[0] === "M" || command[0] === "L")
    return [command[0], x + command[1] * scale, y + command[2] * scale];
  return [
    "C",
    x + command[1] * scale,
    y + command[2] * scale,
    x + command[3] * scale,
    y + command[4] * scale,
    x + command[5] * scale,
    y + command[6] * scale,
  ];
}

/** The mark's subpaths, positioned with its top-left corner at `(x, y)` and scaled to `height`. */
export function kardoMarkPaths(
  x: number,
  y: number,
  height: number,
): readonly MarkPath[] {
  const scale = height / KARDO_MARK_VIEW_HEIGHT;
  return rawPaths.map(({ d, fillRule, opacity }) => ({
    d: d.map((command) => scaleCommand(command, x, y, scale)),
    fillRule,
    ...(opacity === undefined ? {} : { opacity }),
  }));
}
